(function(){const N=NeonCombat,C=Casino192,g=new N.Brawler(),$=x=>document.getElementById(x),c=$('view').getContext('2d');let playing=false;function stage(){g.selectHero('broxton');C.start(g,+$('section').value);g.pending=[];g.enemies=[];g.ai=()=>{};g.reinforce=()=>{};g.camera=+$('camera').value*g.cameraBounds.max;g.player.x=g.player.prevX=g.camera+160;const e=g.spawnCasinoSecurity192(g.camera+670);e.dir=-1;e.cd=999;g.environment156.setOverride({hour:$('sky').value==='night'?23:13,weather:$('sky').value==='night'?'heavyRain':'clear',intensity:$('sky').value==='night'?1:0,wetness:$('sky').value==='night'?1:0,clockPaused:true});playing=false;draw();}
function actor(f){const pv=f.pairVisual,S=N.Forest125.scale(f),z=f.grappleZ||Math.sin((f.jump||0)/.68*Math.PI)*(f.jumpApex||100);c.save();c.translate((pv?pv.cx:f.x)-g.camera,pv?pv.cy:f.y-z);c.scale((pv?.sourceDir||f.dir)*S,S);if(pv){c.rotate(pv.angle*(pv.sourceDir||f.dir));c.translate(0,pv.pivot);}PolishedSprites.draw(c,f,g.time,S);c.restore();}
function draw(){c.setTransform(2,0,0,2,0,0);OutdoorLevelTemplate162.render(c,g,null,()=>{for(const f of [...g.props,...g.enemies,g.player].sort((a,b)=>a.y-b.y))f.casino192?CasinoView192.prop(c,g,f):actor(f);});CasinoView192.foreground(c,g);c.fillStyle='#080e20';c.fillRect(0,0,960,68);c.fillStyle='#f3d895';c.font='bold 15px monospace';c.fillText(g.zoneDefinition.name,18,26);c.font='12px monospace';c.fillStyle='#bce6e2';c.fillText('BROXTON · '+g.player.hp+' HP    SECURITY · 130 HP    '+$('sky').selectedOptions[0].textContent,18,50);$('debug').textContent=JSON.stringify({section:C.section(g),camera:g.camera,worldClock:g.environment156.effective().hour,weather:g.environment156.effective().weather,transition:g.transition?.phase,slots:g.props.filter(p=>p.slot192).map(p=>({number:p.slot192,hp:p.hp,chance:p.dropChance192,rolled:p.lootChecked})),loot:g.items.filter(i=>i.casino192),pendingBoss:g.poolPending192},null,2);}
$('stage').onclick=stage;$('step').onclick=()=>{for(let n=0;n<10;n++)g.tick(1/60,{});draw()};$('break').onclick=()=>{const q=g.props.find(p=>p.slot192&&p.hp>0&&p.x>g.camera);if(!q)return;g.player.x=q.x-65;g.player.y=q.y;g.player.act=null;g.player.cd=0;g.player.stun=g.player.down=0;g.command('attack',{});for(let n=0;n<30;n++)g.tick(1/60,{});draw()};$('clear').onclick=()=>{g.pending=[];g.enemies=[];g.zoneClear=true;if(C.section(g)===2)g.poolPending192=true;draw()};$('travel').onclick=()=>{C.travel(g,C.section(g)+1);playing=true;};$('play').onclick=()=>playing=!playing;let last=0;function loop(t){if(playing&&t-last>1000/60){g.tick(1/60,{});draw();last=t;}requestAnimationFrame(loop)}Promise.resolve(PolishedSprites.ready).then(()=>{stage();requestAnimationFrame(loop)});})();
